import { ActionDefinition } from '../../../Action'
import { TableNameColumn, DocumentIdColumn, TemplateValueColumn } from '../../../../db'

export const updateRecord = ActionDefinition({
    $id: 'f9d01dd2c31332002841b63b12d3aea1',
    name: 'Update Record',
    description:
        'Update an existing record on a ServiceNow table. You can dynamically add and configure fields for the record. Server-side validation rules are enforced (data policy, business rules, dictionary-defined mandatory fields), but UI policy does not apply.',
    inputs: {
        table_name: TableNameColumn({
            label: 'Table',
            mandatory: true,
        }),
        record: DocumentIdColumn({
            label: 'Record',
            mandatory: true,
            maxLength: 40,
            dependent: 'table_name',
        }),
        values: TemplateValueColumn({
            label: 'Fields',
            mandatory: true,
            maxLength: 16000000,
            dependent: 'table_name',
        }),
    },
    outputs: {
        table_name: TableNameColumn({
            label: 'Table',
        }),
        record: DocumentIdColumn({
            label: 'Record',
            dependent: 'table_name',
            maxLength: 40,
        }),
    },
})
